import pathlib,re,subprocess
root=pathlib.Path('/app/dclm')
replacements={}
s=(root/'ray_processing/process.py').read_text()
for name,placeholder in [('AWS_ACCESS_KEY_ID','<your-aws-access-key-id>'),('AWS_SECRET_ACCESS_KEY','<your-aws-secret-access-key>')]:
 for v in re.findall(r'os.environ\\[\"'+name+r'\"\\]\\s*=\\s*\"(["'^"]+)"'"',s): replacements[v]=placeholder
s=(root/'ray_processing/ray_cluster.yaml').read_text()
for name,placeholder in [('AWS_ACCESS_KEY_ID','<your-aws-access-key-id>'),('AWS_SECRET_ACCESS_KEY','<your-aws-secret-access-key>')]:
 for v in re.findall(name+r'=(["'^'"\\s\\'\\\"]+)',s): replacements[v]=placeholder
for pattern,placeholder in [(r'gh[pousr]_[A-Za-z0-9]+','<your-github-token>'),(r'github_pat_[A-Za-z0-9_]+','<your-github-token>'),(r'hf_[A-Za-z0-9]{20,}','<your-huggingface-token>')]:
 for v in re.findall(pattern,s): replacements[v]=placeholder
changed=[]
for p in root.rglob('*'):
 if not p.is_file() or '.git' in p.parts: continue
 data=p.read_bytes(); new=data
 for old,placeholder in replacements.items(): new=new.replace(old.encode(),placeholder.encode())
 if new"'!=data:
  p.write_bytes(new);changed.append(str(p.relative_to(root)))
print('"'Replaced',len(replacements),'distinct credentials in',changed)
assert all(not any(v.encode() in p.read_bytes() for v in replacements) for p in root.rglob('*') if p.is_file() and '.git' not in p.parts)
print('Exact-value scan: PASS')
objects=subprocess.check_output(['git','rev-list','--objects','--all'],cwd=root,text=True).splitlines()
hits=set()
for line in objects:
 oid,_,path=line.partition(' ')
 if not path:continue
 data=subprocess.check_output(['git','cat-file','-p',oid],cwd=root)
 if any(v.encode() in data for v in replacements):hits.add(path)
print('Historical paths containing discovered credentials:',sorted(hits))
